package com.unimote.app.atv

import java.io.ByteArrayInputStream
import java.math.BigInteger
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/** Expected bytes come from the open-source androidtvremote2 client (generated by tools/gen_atv_vectors.py logic). */
class AtvProtoTest {
  private fun hex(s: String) = s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

  @Test fun pairingMessagesMatchTheReferenceClient() {
    assertArrayEquals(hex("080210c80152140a0961747672656d6f74651207556e696d6f7465"), AtvProto.pairingRequest("Unimote"))
    assertArrayEquals(hex("080210c801a201080a04080310061801"), AtvProto.pairingOptions())
    assertArrayEquals(hex("080210c801f201080a04080310061001"), AtvProto.pairingConfiguration())
    assertArrayEquals(hex("080210c801c202220a20000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), AtvProto.pairingSecret(ByteArray(32) { it.toByte() }))
  }

  @Test fun remoteMessagesMatchTheReferenceClient() {
    assertArrayEquals(hex("0a1c08e304121718012201312a0961747672656d6f74653205312e302e30"), AtvProto.remoteConfigureReply())
    assertArrayEquals(hex("120308e304"), AtvProto.remoteSetActive())
    assertArrayEquals(hex("4a020807"), AtvProto.pingResponse(7))
    assertArrayEquals(hex("5204081a1003"), AtvProto.keyInject(26))
    assertArrayEquals(hex("520508a4011001"), AtvProto.keyInject(164, AtvProto.DIRECTION_START_LONG))
    // RemoteMessage.remote_app_link_launch_request (field 90) { app_link (field 1) = "market://launch?id=a.b" }
    assertArrayEquals(hex("d205180a16") + "market://launch?id=a.b".toByteArray(), AtvProto.appLinkLaunch("market://launch?id=a.b"))
  }

  @Test fun parsesWhatATvSends() {
    assertEquals(AtvProto.Remote.Ping(42), AtvProto.parseRemote(hex("4204082a1001")))
    assertEquals(AtvProto.Remote.Start(true), AtvProto.parseRemote(hex("c202020801")))
    assertEquals(AtvProto.Remote.Configure(622), AtvProto.parseRemote(hex("0a0908ee0412040a025456")))
    assertEquals(AtvProto.PairingReply.REQUEST_ACK, AtvProto.parsePairing(hex("080210c8015a040a025456")).kind)
    assertEquals(AtvProto.PairingReply.CONFIGURATION_ACK, AtvProto.parsePairing(hex("080210c801fa0100")).kind)
    assertEquals(402L, AtvProto.parsePairing(hex("0802109203")).status)
  }

  @Test fun framesRoundTripEvenWhenSplit() {
    val body = AtvProto.keyInject(26)
    val framed = AtvProto.frame(body) + AtvProto.frame(body)
    val stream = ByteArrayInputStream(framed)
    assertArrayEquals(body, AtvProto.readFrame(stream))
    assertArrayEquals(body, AtvProto.readFrame(stream))
    assertNull(AtvProto.readFrame(stream))
    assertEquals(1, AtvProto.frame(ByteArray(5)).size - 5) // short bodies: 1-byte length
    assertEquals(2, AtvProto.frame(ByteArray(129)).size - 129) // 128 and up: 2-byte length
  }

  @Test fun garbageNeverThrows() {
    assertEquals(AtvProto.Remote.Other, AtvProto.parseRemote(byteArrayOf()))
    AtvProto.parseRemote(byteArrayOf(0x0A, 0x7F, 1, 2))
    AtvProto.parsePairing(byteArrayOf(0xFF.toByte(), 0xFF.toByte()))
  }

  @Test fun pairingSecretMatchesTheReferenceClient() {
    val cn = BigInteger("", 16); val ce = BigInteger.valueOf(65537)
    val sn = BigInteger("", 16); val se = BigInteger.valueOf(65537)
    assertArrayEquals(hex("907d257cf8b666b8e15c03ee629ee8ed7eb2e1dc2fc9d981101123ef31a92086"), AtvSecret.compute(cn, ce, sn, se, "902B3C"))
    assertArrayEquals(hex("907d257cf8b666b8e15c03ee629ee8ed7eb2e1dc2fc9d981101123ef31a92086"), AtvSecret.compute(cn, ce, sn, se, "902b3c"))
    assertNull(AtvSecret.compute(cn, ce, sn, se, "802B3C")) // first byte does not match the hash
    assertNull(AtvSecret.compute(cn, ce, sn, se, "12345"))
    assertNull(AtvSecret.compute(cn, ce, sn, se, "12345G"))
  }
}

